INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Python-Listen immer langsamer als Arrays in anderen Sprachen?', 2, '[{"text": "Nein", "correct": true, "because": "Listen sind dynamisch und flexibel"}, {"text": "Ja", "correct": false, "because": "Abhängig vom Use-Case"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Struktur wähle ich in Python für schnelle Schlüssel-Wert-Zugriffe?', 3, '[{"text": "Dictionary", "correct": true, "because": "O(1) durch Hashing"}, {"text": "Liste", "correct": false, "because": "O(n) für Suche"}, {"text": "Tuple", "correct": false, "because": "Keine Schlüssel-Wert-Paare"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Operationen sind bei einem Python-Dictionary besonders schnell?', 5, '[{"text": "Schlüsselabfrage", "correct": true, "because": "O(1) im Durchschnitt"}, {"text": "Wert einfügen", "correct": true, "because": "O(1) bei gutem Hash"}, {"text": "Sortieren", "correct": false, "because": "Dicts sind unsortiert"}, {"text": "Lineare Suche", "correct": false, "because": "Nicht primäre Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Listen in Python sind veränderbar. b) Dictionaries nicht.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Dictionaries sind auch mutabel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wahl zwischen Liste und Dictionary in Python?', 4, '[{"text": "Zugriffsgeschwindigkeit", "correct": false, "because": "Entscheidend für Effizienz"}, {"text": "Datenstruktur", "correct": false, "because": "Bestimmt den Use-Case"}, {"text": "Reihenfolge der Einträge", "correct": true, "because": "Nur bei Listen relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Dictionary in Python die Reihenfolge speichert?', 2, '[{"text": "Ja", "correct": true, "because": "Seit Python 3.7 ist die Einfügereihenfolge erhalten"}, {"text": "Nein", "correct": false, "because": "Frühere Versionen hatten keine Garantie"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode nutze ich, um ein Element an eine Python-Liste anzuhängen?', 3, '[{"text": "append()", "correct": true, "because": "Fügt am Ende hinzu"}, {"text": "insert()", "correct": false, "because": "Fügt an spezifischer Position ein"}, {"text": "add()", "correct": false, "because": "Gibt’s bei Listen nicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Strukturen helfen mir in Python bei dynamischen Anwendungen?', 5, '[{"text": "Liste", "correct": true, "because": "Flexibel und veränderbar"}, {"text": "Dictionary", "correct": true, "because": "Schnelle Zugriffe und Änderungen"}, {"text": "String", "correct": false, "because": "Unveränderbar"}, {"text": "Set", "correct": false, "because": "Nur für eindeutige Elemente"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Listen sind gut für geordnete Daten. b) Dictionaries für ungeordnete Schlüssel-Wert-Paare. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Dictionaries sind seit 3.7 geordnet"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht mehr ganz korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, wenn ich in Python nur Schlüssel-Wert-Paare speichere?', 4, '[{"text": "Dictionary", "correct": false, "because": "Perfekt dafür"}, {"text": "Schnelle Zugriffe", "correct": false, "because": "Wichtig für Dicts"}, {"text": "Indexbasierte Zugriffe", "correct": true, "because": "Dictionaries nutzen Schlüssel"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ich eine Liste in Python einfach als Stack nutzen?', 2, '[{"text": "Ja", "correct": true, "because": "append() und pop() sind O(1)"}, {"text": "Nein", "correct": false, "because": "Funktioniert problemlos"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Strukturen haben in Python O(1) für Hinzufügen?', 4, '[{"text": "Liste mit append()", "correct": true, "because": "Am Ende O(1)"}, {"text": "Dictionary", "correct": true, "because": "O(1) für Schlüssel"}, {"text": "Liste mit insert()", "correct": false, "because": "O(n) wegen Verschiebung"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Dictionaries in Python mehr Speicher als Listen brauchen. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Hash-Tabelle Overhead"}, {"text": "Nein", "correct": false, "because": "Listen sind kompakter"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einer Python-Liste für schnelle Änderungen?', 3, '[{"text": "Dynamische Größe", "correct": true, "because": "Ermöglicht einfaches Wachsen"}, {"text": "Sortiergeschwindigkeit", "correct": false, "because": "Sekundär"}, {"text": "Speicherbedarf", "correct": false, "because": "Weniger kritisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Listen können alles speichern. b) Dictionaries nur Zahlen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Dictionaries speichern beliebige Werte"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Strukturen passen in Python für eine Schlüssel-Wert-Datenbank?', 5, '[{"text": "Dictionary", "correct": true, "because": "Schnelle Schlüsselzugriffe"}, {"text": "Liste von Tupeln", "correct": true, "because": "Kann Paare speichern"}, {"text": "Liste allein", "correct": false, "because": "Keine Schlüssel"}, {"text": "String", "correct": false, "because": "Keine Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer Python-Liste für große Daten unwichtig?', 3, '[{"text": "Append-Geschwindigkeit", "correct": false, "because": "Bleibt O(1)"}, {"text": "Speicherbedarf", "correct": false, "because": "Wichtig bei Skalierung"}, {"text": "Sortierfähigkeit", "correct": true, "because": "Sekundär bei rohen Daten"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal mit dem Zugriff? Ist ein Dictionary immer schneller als eine Liste?', 3, '[{"text": "Ja", "correct": true, "because": "O(1) vs. O(n) für Suche"}, {"text": "Nein", "correct": false, "because": "Nur bei Schlüsseln schneller"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Liste in Python auch als Queue taugt?', 2, '[{"text": "Ja", "correct": true, "because": "Mit append() und pop(0)"}, {"text": "Nein", "correct": false, "because": "Effizienzprobleme bei pop(0)"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Struktur wähle ich in Python für eine Aufgabe mit eindeutigen Schlüsseln?', 4, '[{"text": "Dictionary", "correct": true, "because": "Schlüssel sind einzigartig"}, {"text": "Liste", "correct": false, "because": "Keine Schlüssel-Unterstützung"}, {"text": "Tuple", "correct": false, "because": "Unveränderbar"}]');
